"""Regenerate summary.md from candidates.json without re-querying the APIs."""

import json
from pathlib import Path

LIT_DIR = Path(__file__).resolve().parent
CANDIDATES = LIT_DIR / "candidates.json"
SUMMARY = LIT_DIR / "summary.md"


def main() -> None:
    blocks = json.loads(CANDIDATES.read_text(encoding="utf-8"))
    lines = ["# Literature search results", ""]
    lines.append(
        "Auto-generated by `paper/literature/build_related_work.py` "
        "and extended by `add_known_papers.py`. Re-run the relevant "
        "script to refresh.\n"
    )
    for block in blocks:
        lines.append(f"## {block['label']}")
        if block.get("ss_query"):
            lines.append(f"_Semantic Scholar query:_ `{block['ss_query']}`  ")
        if block.get("arxiv_query"):
            lines.append(f"_arXiv query:_ `{block['arxiv_query']}`\n")
        if not block.get("ss_query") and not block.get("arxiv_query"):
            lines.append("")
        if not block.get("papers"):
            lines.append("(no results)\n")
            continue
        for p in block["papers"][:10]:
            title = p["title"]
            authors = ", ".join((p.get("authors") or [])[:3])
            if len(p.get("authors") or []) > 3:
                authors += " et al."
            year = p.get("year") or "n.d."
            venue = p.get("venue") or "—"
            cites = p.get("citations")
            cites_s = f"{cites} citations" if cites else "citations unknown"
            tags = []
            if p.get("arxiv_id"):
                tags.append(f"[arXiv:{p['arxiv_id']}](https://arxiv.org/abs/{p['arxiv_id']})")
            if p.get("doi"):
                tags.append(f"[DOI:{p['doi']}](https://doi.org/{p['doi']})")
            if p.get("local_pdf"):
                tags.append(f"local: `{p['local_pdf']}`")
            tag_s = " · ".join(tags) if tags else ""
            lines.append(f"- **{title}** ({year}). {authors}. _{venue}_, {cites_s}.")
            if tag_s:
                lines.append(f"  {tag_s}")
            if p.get("_why_added"):
                lines.append(f"  _Why added:_ {p['_why_added']}")
            abstract = (p.get("abstract") or "").strip()
            if abstract:
                lines.append(f"  > {abstract[:380]}{'…' if len(abstract) > 380 else ''}")
        lines.append("")

    SUMMARY.write_text("\n".join(lines), encoding="utf-8")
    print(f"Wrote {SUMMARY}")


if __name__ == "__main__":
    main()
